    public EntityList<Incident> incidentList(IncidentQueryParam param)
        throws ServiceException {
        EntityList<Incident> result = new EntityList<>();
        param.setName(CommonUtils.escapeParam(param.getName()));
        param.setSourceObjName(CommonUtils.escapeParam(param.getSourceObjName()));

        if (Objects.isNull(param.getPaging())) {
            param.setPaging(new Paging());
        }

        List<Integer> diagnosticStatus = new ArrayList<>();
        int diagnosticType = 0;

        if (CollectionUtils.isNotEmpty(param.getDiagnosticStatus())) {
            diagnosticStatus = param.getDiagnosticStatus().stream()
                .map(DiagnosticStatusEnum::fromName)
                .map(DiagnosticStatusEnum::getCode)
                .collect(Collectors.toList());
        }

        if (StringUtils.isNotEmpty(param.getDiagnosticType())) {
            DiagnosticTypeEnum statusEnum = DiagnosticTypeEnum.fromName(param.getDiagnosticType());
            diagnosticType = statusEnum.getCode();
        }
        // 基于授权网元进行过滤
        IncidentQueryDto incidentQueryDto = new IncidentQueryDto(param);
        if (!ContextUtils.getContext().getAdmin()) {
            List<String> queryDns = getIncidentQueryDns();
            if (queryDns.isEmpty()) {
                result.setTotal(0);
            } else {
                incidentQueryDto.setDnList(queryDns);
                result.setTotal(incidentDao.getIncidentTotal(incidentQueryDto, diagnosticStatus, diagnosticType, param.getStatusList()));
            }
        } else {
            result.setTotal(incidentDao.getIncidentTotal(incidentQueryDto, diagnosticStatus, diagnosticType, param.getStatusList()));
        }
        if (result.getTotal() > 0) {
            List<Incident> incidentList = incidentDao.getIncidentList(incidentQueryDto, diagnosticStatus, diagnosticType);
            fallbackDiagnosisStatus(incidentList);
            populateEventsForIncident(incidentList);
            populateMoiForAlarmIncidents(incidentList);
            result.setObjects(incidentList);
        }
        return result;
    }

    /**
     * 获取授权网元与当前环境上单告警事件网元的交集
     *
     * @return 授权网元与当前环境上单告警事件网元的交集
     * @throws ServiceException 异常时抛出
     */
    public List<String> getIncidentQueryDns()
        throws ServiceException {
        List<String> queryDns = new ArrayList<>();
        Set<String> authDns = ContextUtils.getContext().getAuthDns();
        List<String> distinctDnList = incidentDao.getDistinctDnList();
        if (distinctDnList.contains(null)) {
            queryDns.add(null);
        }
        if (CollectionUtils.isEmpty(authDns) || CollectionUtils.isEmpty(distinctDnList)) {
            return queryDns;
        }
        queryDns.addAll(distinctDnList.stream().filter(Objects::nonNull).filter(authDns::contains).toList());
        return queryDns;
    }

    public void populateEventsForIncident(List<Incident> incidentList)
        throws ServiceException {
        List<Long> csns = incidentList.stream().map(Incident::getCsn).toList();
        List<Event> eventsByIncidentCsn = incidentDao.getEventsByIncidentCsn(csns);
        Map<Long, List<Event>> eventsMap =
            eventsByIncidentCsn.stream().collect(Collectors.groupingBy(Event::getIncidentCsn));
        for (Incident incident : incidentList) {
            incident.setEvents(eventsMap.get(incident.getCsn()));
        }
    }

