    public ResponseResult performManualDiagnose(IncidentCsn incidentCsn)
        throws ServiceException {
        LOGGER.info("Start performManualDiagnose csn {}", incidentCsn.getIncidentCsn());
        Incident incident = incidentDao.getIncidentByCsn(incidentCsn.getIncidentCsn());

        if (!incident.getDiagnosticStatus().canPerformManualDiagnose()) {
            LOGGER.info("csn:{} is diagnosing, can't manual diagnose.", incidentCsn.getIncidentCsn());
            return ResponseResultHelper.failResponseEntity(ResourceUtil.getMessage(ExceptionInternationalConstant.INCIDENT_DIAGNOSIS_RUNNING,
                ContextUtils.getDefaultLocale()));
        }

        incident.setDiagnosticType(MANUAL);
        incident.setDiagnosticStatus(DiagnosticStatusEnum.PENDING_DIAGNOSIS);
        incidentDao.addIncident(Collections.singletonList(incident));

        try {
            MANUAL_DIAGNOSE_THREAD_POOL.execute(() -> {
                try {
                    incident.setDiagnosticStatus(DIAGNOSING);
                    incidentDao.addIncident(Collections.singletonList(incident));
                    faultDiagnosis(incident);
                    incidentDao.updateDiagnoseEndTime(incident.getCsn(), System.currentTimeMillis());
                } catch (Throwable e) {
                    incident.setDiagnosticStatus(DIAGNOSIS_FAILED);
                    try {
                        incidentDao.addIncident(Collections.singletonList(incident));
                    } catch (ServiceException ex) {
                        LOGGER.error("performManualDiagnose ServiceException csn {}", incidentCsn, ex);
                    }
                    LOGGER.error("performManualDiagnose ServiceException {}", e.getMessage(), e);
                }
            });

        } catch (RejectedExecutionException e) {
            incident.setDiagnosticStatus(DiagnosticStatusEnum.RESOURCE_INSUFFICIENT_NOT_EXECUTED);
            incidentDao.addIncident(Collections.singletonList(incident));
            LOGGER.error("performManualDiagnose RejectedExecutionException {}, csn {}", e.getMessage(), incidentCsn);
            return ResponseResultHelper.failResponseEntity("No resource");

        } catch (Exception e) {
            incident.setDiagnosticStatus(DIAGNOSIS_FAILED);
            incidentDao.addIncident(Collections.singletonList(incident));
            LOGGER.error("performManualDiagnose exception {}, csn {}", e.getMessage(), incidentCsn);
            return ResponseResultHelper.failResponseEntity("Exception");
        }

        LOGGER.info("performManualDiagnose success, csn {}", incidentCsn);
        return ResponseResultHelper.correctResponseEntity("true");
    }

