    /**
     * 智能事件根因分析
     *
     * @param incident 智能事件
     * @return 根因分析结果
     * @throws ServiceException 异常时抛出
     */
    public IncidentRootAnalysisDetailDto incidentRootAnalysis(Incident incident)
        throws ServiceException {
        Long incidentCsn = incident.getCsn();
        LOGGER.info("[incidentRootAnalysis] start to get incident root analysis result with incidentCsn {}",
            incidentCsn);
        ChainReq chainReq = new ChainReq();
        IncidentRootAnalysisDetailDto incidentRootAnalysisDetailDto = new IncidentRootAnalysisDetailDto();
        IncidentRootAnalysisResult incidentRootAnalysisResult = new IncidentRootAnalysisResult();
        try {
            incidentDao.deleteIncidentWorkflowByIncidentCsn(incidentCsn);
            RecipeReq rootRecipeReq = incidentRecipeService.createRootAnalysisRecipeReq(incident);
            // 执行recipe
            chainReq = ChainProcessor.executeWorkflowDiagnosis(rootRecipeReq);
            IncidentWorkflowDetail incidentWorkflowDetail = new IncidentWorkflowDetail();
            incidentWorkflowDetail.setIncidentCsn(incidentCsn);
            incidentWorkflowDetail.setConversationId(chainReq.getConversationId());
            incidentWorkflowDetail.setChatId(chainReq.getChatId());
            incidentWorkflowDetail.setWorkflowId(LLM_ENGINE_INCIDENT_DIAGNOSIS_WORKFLOW);
            // 新增/更新事件诊断工作流信息
            incidentDao.addUpdateIncidentWorkflowByIncidentCsn(incidentCsn, incidentWorkflowDetail);
            // 获取recipe执行结果内容
            WorkflowResult workflowResult = ChainProcessor.getIncidentRootAnalysisResult(chainReq);
            incidentRootAnalysisDetailDto.setAnalysisSuccess(workflowResult.isWorkflowSuccess());
            List<WorkflowStepResult> workflowStepResultList = workflowResult.getStepResult();
            incidentRootAnalysisDetailDto.setStepResult(workflowStepResultList);
            incidentWorkflowDetail.setChainResult(JSON.toJSONString(workflowStepResultList));
            incidentDao.addUpdateIncidentWorkflowByIncidentCsn(incidentCsn, incidentWorkflowDetail);
            String answer = workflowResult.getAnswer();
            incidentRootAnalysisResult = JSON.parseObject(answer, IncidentRootAnalysisResult.class);
            incidentRootAnalysisDetailDto.setRootAnalysisResult(incidentRootAnalysisResult);
        } catch (ServiceException e) {
            LOGGER.error(
                "[incidentRootAnalysis] ServiceException occurred during incident root analysis for incidentCsn={}, msg={}",
                incidentCsn,
                e.getMessage(),
                e);
        } catch (Exception e) {
            LOGGER.error(
                "[incidentRootAnalysis] Exception occurred during incident root analysis for incidentCsn={}, msg={}",
                incidentCsn,
                e.getMessage(),
                e);
        } finally {
            if (StringUtils.isNotEmpty(chainReq.getConversationId())) {
                ChainProcessor.closeConversation(chainReq);
            }
        }
        return incidentRootAnalysisDetailDto;
    }

