        RestfulParametes restfulParametes = new RestfulParametes();
        restfulParametes.setRawData(param);
        LOGGER.info("[faultDiagnosis4Incident] ALARM_FAULT_DIAGNOSIS_PROMPT_URL Param is {}", param);

        RestfulResponse alarmRsp = RestUtil.sendRestRequest(RestConstant.RESTFUL_METHOD_POST,
            ALARM_FAULT_DIAGNOSIS_PROMPT_URL,
            restfulParametes,
            options);

        if (alarmRsp == null) {
            LOGGER.error("[faultDiagnosis4Incident] ALARM_FAULT_DIAGNOSIS_PROMPT_URL response is null");
            throw new ServiceException("[faultDiagnosis4Incident] ALARM_FAULT_DIAGNOSIS_PROMPT_URL response is null");
        }
        if (alarmRsp.getStatus() != RestConstant.STATUS_OK) {
            LOGGER.error("[faultDiagnosis4Incident] ALARM_FAULT_DIAGNOSIS_PROMPT_URL error, status {}",
                alarmRsp.getStatus());
            throw new ServiceException(
                "[faultDiagnosis4Incident] ALARM_FAULT_DIAGNOSIS_PROMPT_URL status:" + alarmRsp.getStatus());
        }

        try {
            String model = llmManager.getActivatedModel();
            if (StringUtils.isNotEmpty(model)) {
                llmResp = LlmInvokeApi.invokeLlm(null, model, alarmRsp.getResponseContent(), null);
            }
        } catch (Exception e) {
            LOGGER.error("LLM invoke api exception, message is {}", e.getMessage());
        }

        LOGGER.info("[faultDiagnosis4Incident] ALARM_FAULT_DIAGNOSIS_PROMPT_URL Resp is {}", llmResp);
        return llmResp;
    }

