    public void fallbackDiagnosisStatus(List<Incident> incidents)
        throws ServiceException {
        List<Long> needUpdate = incidents.stream()
            .filter(incident -> DIAGNOSING.equals(incident.getDiagnosticStatus()))
            .filter(incident -> {
                if (AUTO.equals(incident.getDiagnosticType()) && isTwoHoursPassed(incident.getCreateTime())) {
                    return true;
                }
                return MANUAL.equals(incident.getDiagnosticType()) && isTwoHoursPassed(incident.getDiagnoseStartTime());
            })
            .peek(incident -> incident.setDiagnosticStatus(DIAGNOSIS_FAILED))
            .map(Incident::getCsn)
            .collect(Collectors.toList());

        LOGGER.info("need fallback DiagnosisStatus csnList:{}", needUpdate);
        int nums = incidentDao.updateDiagnosisStatusByCsnList(needUpdate, DIAGNOSIS_FAILED);
        LOGGER.info("update nums{} success.", nums);
        processDiagStartTime(incidents);
    }

    public void processDiagStartTime(List<Incident> incidents) {
        for (Incident incident : incidents) {
            if (incident.getDiagnoseStartTime() == 0 && incident.getDiagnoseEndTime() != 0 && DIAGNOSIS_SUCCESS.equals(
                incident.getDiagnosticStatus())) {
                LOGGER.info("incident Csn:{}, have not diag start time");
                long time = 5 * 60 * 1000L;
                incident.setDiagnoseStartTime(incident.getDiagnoseEndTime() - time);
            }
        }
    }

    public boolean isTwoHoursPassed(Long createTime) {
        if (createTime == null) {
            return false;
        }

        long currentTime = System.currentTimeMillis();

        return (currentTime - createTime) > TWO_HOURS_IN_MILLIS;
    }

    /**
     * 计算时间戳
     *
     * @param num 数量，必须 >= 0
     * @param unit 单位，只能是 "hour" 或 "day"
     * @return 毫秒级时间戳
     * @throws IllegalArgumentException num < 0 或 unit 非法时抛出
     */
    public static long getOccurTimeTimestamp(int num, String unit) {
        if (num < 0) {
            throw new IllegalArgumentException("The value of num must be greater than or equal to 0.");
        }
        if (unit == null || unit.isEmpty()) {
            throw new IllegalArgumentException("The unit parameter cannot be null.");
        }

        ChronoUnit chronoUnit;
        switch (unit.trim().toLowerCase(Locale.ROOT)) {
            case "hour":
                chronoUnit = ChronoUnit.HOURS;
                break;
            case "day":
                chronoUnit = ChronoUnit.DAYS;
                break;
            default:
                throw new IllegalArgumentException("The value of unit must be hour or day.");
        }

        Instant now = Instant.now();
        Instant target = now.minus(num, chronoUnit);
        return target.toEpochMilli();
    }

    /**
     * 添加Incident记录
     *
     * @param incidents 列表
     * @param context 上下文
     * @throws ServiceException 服务异常
     */
    @Transactional(rollbackFor = Exception.class)
    public void addIncident(HttpContext context, List<Incident> incidents)
        throws ServiceException {
        if (incidents == null || incidents.isEmpty()) {
            return;
        }

        List<Event> allEvents = prepareEvents(incidents);
        persistData(incidents, allEvents);
        dispatchTasks(incidents);
    }

    private List<Event> prepareEvents(List<Incident> incidents) {
        List<Event> allEvents = new ArrayList<>();
        for (Incident incident : incidents) {
            List<Long> rootCsn = new ArrayList<>();
            if (incident.getEvents() != null) {
                incident.getEvents().forEach(event -> {
                    event.setIncidentCsn(incident.getCsn());
                    if (event.getRootEventProbability() != null
                        && event.getRootEventProbability() > ROOT_PROBABILITY) {
                        rootCsn.add(event.getCsn());
                    }
                });
                allEvents.addAll(incident.getEvents());
            }
            incident.setReasonIds(convertListToString(rootCsn));
        }
        return allEvents;
    }

    private void persistData(List<Incident> incidents, List<Event> allEvents) throws ServiceException {
        incidents.forEach(incident -> {
            incident.setDiagnosticStatus(DiagnosticStatusEnum.NOT_DIAGNOSED);
        });

        incidentDao.addIncident(incidents);

        if (!allEvents.isEmpty()) {
            incidentDao.addEvent(allEvents);
        }

        incidents.forEach(incident -> {
            incident.setDiagnosticStatus(DiagnosticStatusEnum.PENDING_DIAGNOSIS);
        });
        incidentDao.addIncident(incidents);
    }

    private void dispatchTasks(List<Incident> incidents) throws ServiceException {
        for (Incident incident : incidents) {
            if (ALARM.equals(incident.getCategory())) {
                handleAlarmTask(incident);
                continue;
            }
            submitDiagnosisTask(incident);
        }
    }

    private void handleAlarmTask(Incident incident) throws ServiceException {
        if (TransactionSynchronizationManager.isSynchronizationActive()) {
            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
                @Override
                public void afterCommit() {
                    delayedIncidentScheduler.addIncidentWithDelay(incident);
                }
            });
        } else {
            delayedIncidentScheduler.addIncidentWithDelay(incident);
        }
    }

    private void submitDiagnosisTask(Incident incident) throws ServiceException {
        try {
            THREAD_POOL_EXECUTOR.execute(() -> {
                incident.setDiagnosticStatus(DIAGNOSING);
                try {
                    incidentDao.addIncident(Collections.singletonList(incident));
                    faultDiagnosis(incident);
                    incidentDao.updateDiagnoseEndTime(incident.getCsn(), System.currentTimeMillis());
                } catch (Exception e) {
                    LOGGER.error("Error occurred during fault diagnosis:{}, incident csn {}", e, incident.getCsn());
                }
            });
        } catch (RejectedExecutionException e) {
            handleTaskSubmissionFailure(incident, DiagnosticStatusEnum.RESOURCE_INSUFFICIENT_NOT_EXECUTED,
                "RejectedExecutionException", e.getMessage());
        } catch (Exception e) {
            handleTaskSubmissionFailure(incident, DIAGNOSIS_FAILED, "Exception", e.getMessage());
        }
    }

    private void handleTaskSubmissionFailure(Incident incident, DiagnosticStatusEnum status,
        String errorType, String errorMessage) throws ServiceException {
        incident.setDiagnosticStatus(status);
        incidentDao.addIncident(Collections.singletonList(incident));
        LOGGER.error("{} {}, incidentCsn {}", errorType, errorMessage, incident.getCsn());
    }

    public void alarmDiagnosisByRecipe(Event event, Incident incident, ALarmWhiteListEntry recipeData) {
        try {
            Locale locale = DefaultEnvUtil.getOssLocale();
            String model = llmManager.getActivatedModel();
            RecipeReq recipeReq = alarmRecipeService.createRecipeReq(event, model, recipeData);

            LOGGER.info("alarmDiagnosisByRecipe csn {}, recipe req question: {}",
                incident.getCsn(),
                recipeReq.getQuestion());
            DiagnosisReport report = ChainProcessor.execute(recipeReq);

            if (report != null) {
                processDiagnosisSuccess(report, incident, event, locale);
            } else {
                LOGGER.error("ChainProcessor execute result is null, csn {}", event.getSourceCsn());
                handleDiagnosisFailure(incident);
            }
        } catch (Exception e) {
            LOGGER.error("Error occurred during fault diagnosis:{}, incident csn {}", e, event.getSourceCsn());
            handleDiagnosisFailure(incident);
        }
    }

    private void processDiagnosisSuccess(DiagnosisReport report, Incident incident, Event event, Locale locale)
        throws ServiceException {
        LOGGER.info("csn {}, text report is{}", incident.getCsn(), report.getTextReport());
        Incident latestIncident = incidentDao.getIncidentByCsn(incident.getCsn());
        LLMReport llmReport = report.getLlmReport() != null ? report.getLlmReport() : new LLMReport();
        latestIncident.setDiagnosisResult(convertCheckList(llmReport));
        String textReport = report.getTextReport() != null ? report.getTextReport() : "";
        // 过滤英文场景下的非英文字符
        if (!Objects.equals(locale.getLanguage(), Constants.LANG_ZH)) {
            String regex = "[^a-zA-Z0-9\\s\\p{Punct}]";
            textReport = textReport.replaceAll(regex, "");
        }
        updateDiagnosis(textReport, latestIncident, report.getSuccessStatus());

        long curTime = System.currentTimeMillis();
        String fileName =
            "diagnosisReport_" + event.getOccurTime() + '_' + event.getVnfName() + '_' + event.getSourceCsn()
                + '_' + curTime + ".txt";

        String txtReport = buildCheckDetail(
            textReport,
            llmReport.getCheckItem(),
            event,
            curTime,
            locale
        );

        LOGGER.info("csn {}, fileName{}, txtReport : {}", incident.getCsn(), fileName, txtReport);
        uploadSftpFile(fileName, txtReport);
        incidentDao.updateIncidentReportPath(incident.getCsn(), fileName);
    }

    private void handleDiagnosisFailure(Incident incident) {
        try {
            Locale locale = DefaultEnvUtil.getOssLocale();
            Incident latestIncident = incidentDao.getIncidentByCsn(incident.getCsn());
            latestIncident.setDiagnosticStatus(DIAGNOSIS_FAILED);
            latestIncident.setRepairAdvice(ResourceUtil.getMessage(IncidentConstant.ALARM_DIAGNOSIS_GENERAL_FAIL_DETAIL,
                locale));
            latestIncident.setDiagnosisStatusDetail(ResourceUtil.getMessage(IncidentConstant.ALARM_DIAGNOSIS_GENERAL_FAIL_DETAIL,
                locale));
            latestIncident.setDiagnosisResult(convertCheckList(new LLMReport()));
            incidentDao.addIncident(Collections.singletonList(latestIncident));
        } catch (Exception dbException) {
            LOGGER.error("Failed to update incident status to FAILED, csn {}", incident.getCsn(), dbException);
        }
    }

    private String buildCheckDetail(String txtReport, List<CheckItem> checkItems, Event event, long time,
        Locale locale) {
        StringBuilder markdown = new StringBuilder();

        appendAlarmInfo(markdown, event, time, locale);

        markdown.append(txtReport);

        if (checkItems != null && !checkItems.isEmpty()) {
            appendCheckItemsTable(markdown, checkItems, locale);
        }

        return markdown.toString();
    }

    private void appendAlarmInfo(StringBuilder markdown, Event event, long time, Locale locale) {
        markdown.append("## ")
            .append(ResourceUtil.getMessage(LogConstant.REPORT_ALARM_INFO, locale))
            .append("\n")
            .append("- ")
            .append(ResourceUtil.getMessage(LogConstant.REPORT_ALARM_ID, locale))
            .append(":")
            .append(event.getEventId())
            .append("\n")
            .append("- ")
            .append(ResourceUtil.getMessage(LogConstant.REPORT_ALARM_TITLE, locale))
            .append(":")
            .append(event.getName())
            .append("\n")
            .append("- ")
            .append(ResourceUtil.getMessage(LogConstant.REPORT_VNF_NAME, locale))
            .append(":")
            .append(event.getVnfName())
            .append("\n")
            .append("- ")
            .append(ResourceUtil.getMessage(LogConstant.REPORT_ALARM_CSN, locale))
            .append(":")
            .append(event.getSourceCsn())
            .append("\n")
            .append("- ")
            .append(ResourceUtil.getMessage(LogConstant.REPORT_OCCUR_TIME, locale))
            .append(":")
            .append(formatTimestamp(event.getOccurTime()))
            .append("\n")
            .append("- ")
            .append(ResourceUtil.getMessage(LogConstant.REPORT_REPORT_TIME, locale))
            .append(":")
            .append(formatTimestamp(time))
            .append("\n\n");
    }

    private void appendCheckItemsTable(StringBuilder markdown, List<CheckItem> checkItems, Locale locale) {
        markdown.append("\n\n## ")
            .append(ResourceUtil.getMessage(LogConstant.REPORT_CHECK_ITEMS, locale))
            .append("\n\n");

        markdown.append("| ").append(ResourceUtil.getMessage(LogConstant.REPORT_TABLE_SEQ, locale))
            .append(" | ").append(ResourceUtil.getMessage(LogConstant.REPORT_TABLE_ITEM, locale))
            .append(" | ").append(ResourceUtil.getMessage(LogConstant.REPORT_TABLE_STATUS, locale))
            .append(" | ").append(ResourceUtil.getMessage(LogConstant.REPORT_TABLE_DETAILS, locale))
            .append(" |\n");

        markdown.append("|----|------|--------|---------|\n");

        for (int i = 0; i < checkItems.size(); i++) {
            CheckItem item = checkItems.get(i);
            markdown.append("| ")
                .append(i + 1) // 序号从1开始
                .append(" | ")
                .append(escapeMarkdownCell(item.getName() != null ? item.getName() : ""))
                .append(" | ")
                .append(getStatusText(item.getStatus(), locale))
                .append(" | ")
                .append(escapeMarkdownCell(item.getDetails() != null ? item.getDetails() : ""))
                .append(" |\n");
        }
    }

    private static String formatTimestamp(Long timestamp) {
        if (timestamp == null || timestamp == 0L) {
            return "";
        }
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        return sdf.format(new Date(timestamp));
    }

    /**
     * 根据状态值返回对应的状态文本
     *
     * @param status 状态值（0表示正常，-1表示异常）
     * @param locale 国际化
     * @return 状态文本
     */
    private static String getStatusText(int status, Locale locale) {
        switch (status) {
            case 0:
                return ResourceUtil.getMessage(LogConstant.REPORT_STATUS_NORMAL, locale);
            case -1:
                return ResourceUtil.getMessage(LogConstant.REPORT_STATUS_EXCEPTION, locale);
            default:
                // 其余的值不展示数据
                return "";
        }
    }

    /**
     * 转义Markdown表格单元格中的特殊字符
     *
     * @param cellContent 单元格内容
     * @return 转义后的内容
     */
    private static String escapeMarkdownCell(String cellContent) {
        if (cellContent == null) {
            return "";
        }
        // 转义管道符和反斜杠
        return cellContent.replace("\\", "\\\\").replace("|", "\\|");
    }

